CREATE TABLE IF NOT EXISTS roles (role_id SERIAL PRIMARY KEY, name VARCHAR(20) UNIQUE NOT NULL, description VARCHAR(100));
CREATE TABLE IF NOT EXISTS categories (category_id SERIAL PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL, description VARCHAR(200));
CREATE TABLE IF NOT EXISTS priorities (priority_id SERIAL PRIMARY KEY, name VARCHAR(20) UNIQUE NOT NULL, level INT NOT NULL, description VARCHAR(100));
CREATE TABLE IF NOT EXISTS statuses (status_id SERIAL PRIMARY KEY, name VARCHAR(20) UNIQUE NOT NULL, description VARCHAR(100));
CREATE TABLE IF NOT EXISTS users (user_id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role_id INT NOT NULL REFERENCES roles(role_id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tickets (ticket_id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(user_id), category_id INT REFERENCES categories(category_id), priority_id INT NOT NULL REFERENCES priorities(priority_id), status_id INT NOT NULL REFERENCES statuses(status_id), assigned_to BIGINT REFERENCES users(user_id), title VARCHAR(200) NOT NULL, description TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, closed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments (comment_id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(ticket_id), user_id BIGINT NOT NULL REFERENCES users(user_id), text TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_history (history_id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(ticket_id), old_status_id INT REFERENCES statuses(status_id), new_status_id INT NOT NULL REFERENCES statuses(status_id), changed_by BIGINT NOT NULL REFERENCES users(user_id), changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ml_predictions (prediction_id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(ticket_id), predicted_category_id INT NOT NULL REFERENCES categories(category_id), confidence NUMERIC(5,4) NOT NULL CHECK (confidence BETWEEN 0 AND 1), model_version VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attachments (attachment_id BIGSERIAL PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(ticket_id), user_id BIGINT NOT NULL REFERENCES users(user_id), file_name VARCHAR(255) NOT NULL, file_path VARCHAR(500) NOT NULL, file_type VARCHAR(100), file_size BIGINT, uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_tickets_user ON tickets(user_id);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status_id);
CREATE INDEX IF NOT EXISTS idx_comments_ticket ON comments(ticket_id);
